knowledge_base = {
    "python": "Python is a high-level, interpreted programming language known for readability and wide application in web development, data science, and AI.",
    "docker": "Docker is a containerization platform that packages applications and dependencies into lightweight, portable containers.",
    "sql": "SQL (Structured Query Language) is a domain-specific language for managing and querying relational databases.",
    "agent": "An AI agent is a software system that perceives its environment, makes decisions, and takes actions to achieve goals.",
}

def rag_agent(task, knowledge):
    if task.startswith("ask:"):
        topic = task.split(":", 1)[1].strip().lower()
        knowledge_lower = {k.lower(): k for k in knowledge}
        if topic in knowledge_lower:
            real_key = knowledge_lower[topic]
            text = knowledge[real_key]
            return {"task": task, "knowledge": text, "result": f"I found information about {real_key}.", "status": "ok"}
        else:
            return {"task": task, "knowledge": "", "result": "I don't know about that topic", "status": "error"}
    elif task == "list":
        topics = ", ".join(knowledge.keys())
        return {"task": task, "knowledge": topics, "result": f"Available topics: {topics}", "status": "ok"}
    else:
        return {"task": task, "knowledge": "", "result": "I can only answer about known topics", "status": "error"}
